function w({registerIndicator:m,nulls:p}){m({id:"oa-atr",name:"Average True Range (ATR)",category:"Volatility",placement:"pane",inputs:[{key:"length",type:"number",label:"Length",default:14,min:1,max:5e3,step:1,tooltip:"Number of bars used for the ATR calculation."}],plots:[{key:"atr",type:"line",title:"ATR",style:{color:"#ffeb3b",lineWidth:2}}],calc(r,N){const n=Math.max(1,Math.floor(Number(N.length)||14)),s=r.length,c=new Array(s).fill(NaN),g=1e-10,y=1-1/n;let e=NaN,a=0,o=1;for(let t=0;t<s;t++){const l=r[t],h=l.high,u=l.low,i=l.close;t===0&&(e=Number.isFinite(i)?i:NaN);const A=h-u,R=Math.abs(h-e),d=Math.abs(u-e),b=Math.max(A,R,d);if(e=i,!Number.isFinite(b))continue;a=(a*(n-1)+b)/n,o*=y;const f=o>g?a/(1-o):a;Number.isFinite(f)&&(c[t]=f)}return{atr:p(c)}}})}export{w as default};
